package com.timetune.controller;
import com.timetune.domain.Song;import com.timetune.service.SongCatalogService;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/songs") public class SongController {private final SongCatalogService catalog;public SongController(SongCatalogService c){catalog=c;}public record SongDto(String id,String title,String artist,int releaseYear,String genre){}@GetMapping public List<SongDto> all(){return catalog.all().stream().map(SongController::dto).toList();}@GetMapping("/{id}")public SongDto get(@PathVariable String id){return dto(catalog.require(id));}public static SongDto dto(Song s){return new SongDto(s.getId().toString(),s.getTitle(),s.getArtist(),s.getReleaseYear(),s.getGenre());}}
